"use client";

import React, { useState } from "react";
import dynamic from "next/dynamic";
import { 
  Briefcase, Clock, Calendar, AlertCircle, TrendingUp, 
  History, ArrowDownRight, ArrowUpRight, Plane, Stethoscope, 
  ChevronRight, PieChart, Activity
} from "lucide-react";
import { ApexOptions } from "apexcharts";

// Lazy Load Chart to prevent SSR issues
const ReactApexChart = dynamic(() => import("react-apexcharts"), { ssr: false });

// --- CONFIGURATION ---
const LEAVE_TYPES = [
  { 
    id: "annual", 
    title: "Annual Leave", 
    total: 18, 
    used: 12, 
    accrued: 15, 
    carryForward: 3,
    icon: Plane, 
    color: "text-blue-600", 
    bg: "bg-blue-600", 
    lightBg: "bg-blue-50 dark:bg-blue-900/10",
    gradient: "from-blue-500 to-indigo-600"
  },
  { 
    id: "sick", 
    title: "Sick Leave", 
    total: 12, 
    used: 4, 
    accrued: 12, 
    carryForward: 0,
    icon: Stethoscope, 
    color: "text-rose-600", 
    bg: "bg-rose-600", 
    lightBg: "bg-rose-50 dark:bg-rose-900/10",
    gradient: "from-rose-500 to-pink-600"
  },
  { 
    id: "casual", 
    title: "Casual Leave", 
    total: 7, 
    used: 4, 
    accrued: 7, 
    carryForward: 0,
    icon: Briefcase, 
    color: "text-amber-600", 
    bg: "bg-amber-600", 
    lightBg: "bg-amber-50 dark:bg-amber-900/10",
    gradient: "from-amber-500 to-orange-600"
  },
  { 
    id: "comp", 
    title: "Comp Off", 
    total: 5, 
    used: 2, 
    accrued: 5, 
    carryForward: 0,
    icon: Clock, 
    color: "text-emerald-600", 
    bg: "bg-emerald-600", 
    lightBg: "bg-emerald-50 dark:bg-emerald-900/10",
    gradient: "from-emerald-500 to-teal-600"
  },
];

const HISTORY_LOG = [
  { id: 1, date: "2026-02-01", type: "Accrual", category: "Annual Leave", value: "+1.5", desc: "Monthly Credit" },
  { id: 2, date: "2026-01-20", type: "Usage", category: "Sick Leave", value: "-3.0", desc: "LR-001 (Dental)" },
  { id: 3, date: "2026-01-15", type: "Usage", category: "Annual Leave", value: "-5.0", desc: "LR-002 (Japan Trip)" },
  { id: 4, date: "2026-01-01", type: "Adjustment", category: "Annual Leave", value: "+3.0", desc: "Carry Forward 2025" },
];

export default function EliteTimeOffBalance() {
  const [selectedType, setSelectedType] = useState("annual");

  // --- CHART OPTIONS (Premium Style) ---
  const chartOptions: ApexOptions = {
    chart: {
      type: "bar",
      toolbar: { show: false },
      fontFamily: "inherit",
      background: "transparent",
    },
    colors: ["#6366f1", "#f43f5e", "#f59e0b", "#10b981"],
    plotOptions: {
      bar: {
        borderRadius: 6,
        columnWidth: "40%",
        distributed: true, // Different color per column
      },
    },
    dataLabels: { enabled: false },
    grid: {
      show: true,
      borderColor: 'rgba(128, 128, 128, 0.1)',
      strokeDashArray: 4,
      xaxis: { lines: { show: false } },   
    },
    xaxis: {
      categories: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
      axisBorder: { show: false },
      axisTicks: { show: false },
      labels: {
        style: { colors: '#94a3b8', fontSize: '10px', fontWeight: 600 }
      }
    },
    yaxis: {
      show: true,
      labels: {
        style: { colors: '#94a3b8', fontSize: '10px', fontWeight: 600 },
        formatter: (val) => `${val}d`
      }
    },
    tooltip: {
      theme: 'dark',
      x: { show: false },
      y: { formatter: (val) => `${val} days taken` }
    },
    legend: { show: false }
  };

  const chartSeries = [{
    name: "Days Taken",
    data: [2, 3, 0, 5, 1, 0, 2, 0, 1, 4, 0, 2] // Mock yearly distribution
  }];

  return (
    <div className="h-screen w-full bg-[#f8fafc] dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 flex flex-col overflow-hidden p-4 gap-4">
      
      {/* 1. TITLE BAR */}
      <div className="flex-none flex items-center justify-between px-2">
        <h1 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">Time Off Analytics</h1>
        <div className="flex items-center gap-2 px-3 py-1 bg-white dark:bg-[#111] rounded-full border border-slate-200 dark:border-white/10 shadow-sm">
           <div className="h-2 w-2 rounded-full bg-indigo-500 animate-pulse" />
           <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Data: Realtime</span>
        </div>
      </div>

      <div className="flex-1 flex gap-4 overflow-hidden min-h-0">
        
        {/* === LEFT PANEL: WALLET & BALANCES === */}
        <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col overflow-hidden">
             
             {/* A. SUMMARY CARDS */}
             <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar">
                
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">My Wallet</span>
                   <button className="text-[10px] font-bold text-indigo-600 hover:underline">View Policy</button>
                </div>

                {LEAVE_TYPES.map((type) => {
                   const percentage = (type.used / type.total) * 100;
                   const remaining = type.total - type.used;
                   const isSelected = selectedType === type.id;

                   return (
                      <div 
                        key={type.id}
                        onClick={() => setSelectedType(type.id)}
                        className={`group relative overflow-hidden rounded-2xl border transition-all cursor-pointer ${
                           isSelected 
                             ? "shadow-xl ring-2 ring-indigo-500 border-transparent transform scale-[1.02] z-10" 
                             : "bg-white dark:bg-[#151515] border-slate-100 dark:border-white/5 hover:border-indigo-200 dark:hover:border-indigo-900"
                        }`}
                      >
                         {/* Card Background Gradient (Visible on Select) */}
                         {isSelected && <div className={`absolute inset-0 opacity-[0.03] bg-gradient-to-br ${type.gradient}`} />}
                         
                         <div className="p-5 relative z-10">
                            <div className="flex justify-between items-start mb-4">
                               <div className="flex items-center gap-3">
                                  <div className={`p-2.5 rounded-xl ${type.lightBg}`}>
                                     <type.icon size={18} className={type.color} />
                                  </div>
                                  <div>
                                     <h3 className="text-sm font-black text-slate-900 dark:text-white">{type.title}</h3>
                                     <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Quota: {type.total} Days</p>
                                  </div>
                               </div>
                               <div className="text-right">
                                  <h2 className={`text-2xl font-black ${type.color}`}>{remaining}</h2>
                                  <p className="text-[9px] font-bold text-slate-400 uppercase">Available</p>
                               </div>
                            </div>

                            {/* Progress Bar */}
                            <div className="space-y-1.5">
                               <div className="flex justify-between text-[10px] font-bold text-slate-500">
                                  <span>{type.used} Used</span>
                                  <span>{percentage.toFixed(0)}%</span>
                               </div>
                               <div className="h-2 w-full bg-slate-100 dark:bg-white/10 rounded-full overflow-hidden">
                                  <div className={`h-full rounded-full ${type.bg} transition-all duration-1000 ease-out`} style={{ width: `${percentage}%` }} />
                               </div>
                            </div>

                            {/* Mini Details (Expand on Select) */}
                            {isSelected && (
                               <div className="mt-4 pt-4 border-t border-slate-100 dark:border-white/5 grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                                  <div>
                                     <p className="text-[9px] font-bold text-slate-400 uppercase">Accrued YTD</p>
                                     <p className="text-xs font-bold text-slate-700 dark:text-slate-300">+{type.accrued} days</p>
                                  </div>
                                  <div className="text-right">
                                     <p className="text-[9px] font-bold text-slate-400 uppercase">Carry Fwd</p>
                                     <p className="text-xs font-bold text-slate-700 dark:text-slate-300">+{type.carryForward} days</p>
                                  </div>
                               </div>
                            )}
                         </div>
                      </div>
                   );
                })}
             </div>
        </div>

        {/* === RIGHT PANEL: ANALYTICS & HISTORY === */}
        <div className="flex-[1.5] flex flex-col gap-4 overflow-hidden">
           
           {/* A. CHART SECTION */}
           <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col relative overflow-hidden">
              <div className="p-6 border-b border-slate-100 dark:border-white/5 flex justify-between items-center">
                 <div className="flex items-center gap-2">
                    <PieChart size={16} className="text-indigo-500" />
                    <h3 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">Usage Trends</h3>
                 </div>
                 <select className="bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 text-[10px] font-bold rounded-lg px-2 py-1 outline-none">
                    <option>2026</option>
                    <option>2025</option>
                 </select>
              </div>
              <div className="flex-1 p-4 min-h-[200px]">
                 <ReactApexChart options={chartOptions} series={chartSeries} type="bar" height="100%" />
              </div>
           </div>

           {/* B. TRANSACTION HISTORY (Audit Log) */}
           <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col overflow-hidden">
              <div className="p-5 border-b border-slate-100 dark:border-white/5 flex justify-between items-center bg-slate-50/50 dark:bg-white/[0.02]">
                 <div className="flex items-center gap-2">
                    <History size={16} className="text-slate-400" />
                    <h3 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">Balance History</h3>
                 </div>
                 <button className="text-[10px] font-bold text-indigo-600 hover:underline">Download Report</button>
              </div>
              
              <div className="flex-1 overflow-y-auto p-0 custom-scrollbar">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 dark:bg-white/5 sticky top-0 z-10">
                       <tr>
                          <th className="px-5 py-3 text-[9px] font-black uppercase text-slate-400 tracking-wider">Date</th>
                          <th className="px-5 py-3 text-[9px] font-black uppercase text-slate-400 tracking-wider">Category</th>
                          <th className="px-5 py-3 text-[9px] font-black uppercase text-slate-400 tracking-wider">Description</th>
                          <th className="px-5 py-3 text-[9px] font-black uppercase text-slate-400 tracking-wider text-right">Value</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                       {HISTORY_LOG.map((log) => (
                          <tr key={log.id} className="group hover:bg-slate-50/50 dark:hover:bg-white/[0.02] transition-colors">
                             <td className="px-5 py-3.5">
                                <div className="flex items-center gap-2">
                                   {log.type === 'Accrual' || log.type === 'Adjustment' 
                                      ? <div className="p-1 rounded bg-emerald-50 text-emerald-600"><ArrowUpRight size={10} /></div>
                                      : <div className="p-1 rounded bg-rose-50 text-rose-600"><ArrowDownRight size={10} /></div>
                                   }
                                   <span className="text-xs font-bold text-slate-700 dark:text-slate-300 font-mono">{log.date}</span>
                                </div>
                             </td>
                             <td className="px-5 py-3.5">
                                <span className="text-xs font-medium text-slate-600 dark:text-slate-400">{log.category}</span>
                             </td>
                             <td className="px-5 py-3.5">
                                <span className="text-xs font-medium text-slate-500">{log.desc}</span>
                             </td>
                             <td className="px-5 py-3.5 text-right">
                                <span className={`text-xs font-black px-2 py-1 rounded-md ${
                                   log.value.startsWith('+') 
                                      ? 'bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600' 
                                      : 'bg-rose-50 dark:bg-rose-900/10 text-rose-600'
                                }`}>
                                   {log.value}
                                </span>
                             </td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>

        </div>
      </div>
    </div>
  );
}